"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 plan 7.5, the row "each rival at its best setting on the split" (non-confirmatory; does not change the
decision table). Written 2026-11-21 before the freeze (pre-test code review C-M6), so the rule is fixed before any test
number exists: the best candidate on the split itself, by the plan's operating-point rule (floors first, then the
five-part mean), and ours minus it with the plan's interval.
- B1-strong: every combination of the rule grid (p1v4_b1.Grid) on the split, chosen by p1v4_b1.choose.
- B2-local: every K and reading the final run wrote (p1v4_final local b2local writes K 6, 24, 48 and both readings),
  thresholds by p1v4_score.operating_point on the split.
- B2-fast, B2-strong, B3: every setting of the rival's dev search with the prompt variant of its frozen setting in the
  day's mode (answers mode: the settings of the dev answers log; probability mode: the dev operating-point log), asked
  on the split through p1v4_api.run (final folders, whole rounds until no question is missing), thresholds by the
  operating-point rule on the split. Prompts are not changed (plan 7.5).
On dev (rehearsal) nothing is asked: the stored dev scores of every candidate are read.
Commands:
  ask <split> <key json>     the API candidates on the split (test and replication after the freeze only)
  report <split>             -> results/main_v04/best_on_test_<split>.json
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_best_on_test.py ask|report <split> [key]
"""
import json
import os
import re
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_api as A  # noqa: E402
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
SD = {"B2-fast": "b2fast", "B2-strong": "b2strong", "B3": "b3"}


def variant(setting):
    return re.fullmatch(r"[KA]\d+_(?:think|nothink)(?:_(note|prec))?", setting).group(1)


def candidates(name, mode, st):
    """Plan 7.5's candidates with the prompt of the frozen setting in this mode (the prompt is not changed): B2-fast and
    B2-strong 6, 24 or 48 examples, B3 0 or 6 audio examples, each with and without thinking."""
    frozen = st["api"][name][mode]["setting"]
    v = variant(frozen)
    sfx = f"_{v}" if v else ""
    ns = (0, 6) if name == "B3" else (6, 24, 48)
    kind = "A" if name == "B3" else "K"
    return [f"{kind}{n}_{t}{sfx}" for n in ns for t in ("nothink", "think")]


def score_path(name, setting, split, mode):
    sd = SD[name]
    if split == "dev":
        return (f"{R}/api/{sd}/answers/scores_dev_{setting}.json" if mode == "answers"
                else f"{R}/api/{sd}/scores_dev_{setting}.json")
    return f"{R}/final/{split}/api/{sd}/scores_{split}_{setting}{'_answers' if mode == 'answers' else ''}.json"


def ask(split, key_path, rounds=8, max_usd=3000.0):
    """Runs before any metric (post-fix review B1: the perception gap of amendment 11.1 reads B2-strong's K48
    no-thinking output from here on an answers-only day), the same day as the rival's drift check: each rival needs
    p1v4_api.ok_today (amendment 13.2 and its supplement). Re-asked in whole rounds until no question is missing; a
    probability-mode answer without logprobs or the budget stops the command (as p1v4_api.final_run)."""
    import time
    if split == "dev":
        raise SystemExit("dev uses the stored candidates; nothing to ask")
    import p1v4_test_report as TR
    st = A.frozen(split)
    modes = TR.api_modes(split)
    spent, skipped = 0.0, {}
    for name, sd in SD.items():
        ok, why = A.ok_today(sd, split, st)              # each rival on its own gate (fix check minor 1)
        if not ok:
            skipped[name] = why
            print(f"{name} skipped today: {why} (amendment 13.2)", flush=True)
            continue
        mode = modes[name]
        for setting in candidates(name, mode, st):
            for rnd in range(1, rounds + 1):
                res = A.run(sd, setting, key_path, split=split, answers=mode == "answers", final=True,
                            max_usd=max_usd - spent)
                spent += res["usd"]
                if res["stop_kind"] == "no_logprobs":
                    raise SystemExit(f"{name} {setting}: logprobs lost ({res['stop']}); amendment 2.3: `switch`, then "
                                     f"ask again")
                if res["stop_kind"] == "budget" or spent >= max_usd:
                    raise SystemExit(f"budget ${max_usd:.0f} reached at {name} {setting}")
                if res["expected"] - res["already"] - res["answered"] <= 0:
                    break
                time.sleep(min(600, 60 * rnd))
            missing = A.split_scores(sd, setting, split, mode == "answers", final=True)   # stops if any is missing
            print(f"{name} {setting} ({mode}) on {split}: {missing} missing, ${spent:.2f} so far", flush=True)
    if skipped:                                          # the step is not complete: ask again on a passing day
        raise SystemExit(f"not asked today: {skipped}")


def report(split):
    import p1v4_b1 as B1
    import p1v4_test_report as TR
    st = A.frozen(split)
    rows = D.load_rows(split)
    groups = S.load_groups(split)
    man = TR.final_manifest(split, st)
    T_ours = S.unit_table(rows, TR.decisions(man[TR.OURS]), groups)
    modes = TR.api_modes(split)
    out = {"split": split, "note": "non-confirmatory (plan 7.5); thresholds and settings chosen on this split", "rivals": {}}

    def put(name, best, T_best):
        c = S.interval(T_ours, T_best, "primary")
        out["rivals"][name] = {**best, "ours_minus_best": {"point": c["point"], "ci95": c["ci95"]}}
        print(f"{name}: best {best} -> ours minus best {c['point']:+.4f} [{c['ci95'][0]:+.4f}, {c['ci95'][1]:+.4f}]",
              flush=True)
    # B1-strong: the whole grid on the split
    phrases = json.load(open(f"{R}/b1/mined_phrases.json"))
    pts = B1.point_inputs(rows, C.Context(split), phrases)
    grid = B1.Grid()
    primary, _, floors = B1.evaluate(rows, pts, grid)
    i, met, _ = B1.choose(primary, floors)
    put("B1-strong", {"setting": grid.setting(i), "primary": float(primary[i]), "floors_met": bool(met)},
        S.unit_table(rows, B1.decisions_for(pts, grid, i), groups))
    # B2-local: every K and reading written by the final run (dev: the stored dev scores)
    d = f"{R}/final/{split}/b2local" if split != "dev" else f"{R}/b2local"
    best = None
    for K in (6, 24, 48):
        for rd in ("first", "label"):
            p = f"{d}/scores_{split}_K{K}_{rd}.json"
            if not os.path.exists(p):
                continue
            sc = TR.keyed(json.load(open(p)))
            op = S.operating_point(rows, sc)
            rank = (op["floors_met"], op["primary"], op["lowest_floor"])
            if best is None or rank > best[0]:
                best = (rank, {"K": K, "reading": rd, "primary": op["primary"], "th_s": op["th_s"],
                               "th_r": op["th_r"], "floors_met": op["floors_met"]}, sc)
    if best:
        b = best[1]
        put("B2-local", b, S.unit_table(rows, S.decide(best[2], b["th_s"], b["th_r"]), groups))
    # API rivals
    for name in SD:
        mode = modes[name]
        best, tried = None, []
        for setting in candidates(name, mode, st):
            p = score_path(name, setting, split, mode)
            if not os.path.exists(p):
                if split != "dev":
                    raise SystemExit(f"{p} missing: run `ask` first")
                continue
            sc = TR.keyed(json.load(open(p)))
            op = S.operating_point(rows, sc)
            tried.append({"setting": setting, "primary": op["primary"], "floors_met": op["floors_met"]})
            rank = (op["floors_met"], op["primary"], op["lowest_floor"])
            if best is None or rank > best[0]:
                best = (rank, {"setting": setting, "mode": mode, "primary": op["primary"], "th_s": op["th_s"],
                               "th_r": op["th_r"], "floors_met": op["floors_met"]}, sc)
        if best:
            b = best[1]
            put(name, {**b, "candidates": tried}, S.unit_table(rows, S.decide(best[2], b["th_s"], b["th_r"]), groups))
    json.dump(out, open(f"results/main_v04/best_on_test_{split}.json", "w"), indent=1, default=str)
    print("wrote", f"results/main_v04/best_on_test_{split}.json")


if __name__ == "__main__":
    a = sys.argv[1:]
    if a[0] == "ask":
        ask(a[1], a[2])
    elif a[0] == "report":
        report(a[1])
    else:
        raise SystemExit(__doc__)
